CREATE TABLE `pediu_coupons` (`id` int NOT NULL AUTO_INCREMENT, `code` varchar(40) NOT NULL, `type` varchar(16) NOT NULL, `value` decimal(10,2) NOT NULL, `minSubtotal` decimal(10,2) DEFAULT '0.00' NOT NULL, `maxDiscount` decimal(10,2), `active` int DEFAULT 1 NOT NULL, `expiresAt` timestamp NULL, `createdAt` timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `pediu_coupon_code_unique` (`code`));
CREATE TABLE `pediu_order_reviews` (`id` int NOT NULL AUTO_INCREMENT, `orderId` int NOT NULL, `userId` int NOT NULL, `target` varchar(16) NOT NULL, `productId` int, `rating` int NOT NULL, `comment` text, `createdAt` timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `pediu_review_unique` (`orderId`,`userId`,`target`,`productId`), KEY `pediu_review_order_idx` (`orderId`));
CREATE TABLE `pediu_delivery_events` (`id` int NOT NULL AUTO_INCREMENT, `orderId` int NOT NULL, `eventType` varchar(32) NOT NULL, `latitude` decimal(10,7), `longitude` decimal(10,7), `createdAt` timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY (`id`), KEY `pediu_delivery_events_order_created_idx` (`orderId`,`createdAt`));
CREATE TABLE `pediu_chat_messages` (`id` int NOT NULL AUTO_INCREMENT, `orderId` int, `userId` int NOT NULL, `role` varchar(16) NOT NULL, `body` varchar(2000) NOT NULL, `createdAt` timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY (`id`), KEY `pediu_chat_order_created_idx` (`orderId`,`createdAt`));
